CREATE TABLE medicines(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,notes TEXT,active INTEGER NOT NULL DEFAULT 1,start_date TEXT,end_date TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE medicine_times(id INTEGER PRIMARY KEY AUTOINCREMENT,medicine_id INTEGER NOT NULL REFERENCES medicines(id) ON DELETE CASCADE,time TEXT NOT NULL,UNIQUE(medicine_id,time));
CREATE TABLE dose_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,medicine_id INTEGER NOT NULL REFERENCES medicines(id),medicine_time_id INTEGER REFERENCES medicine_times(id) ON DELETE SET NULL,scheduled_date TEXT NOT NULL,scheduled_time TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('taken','missed')),actual_taken_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(medicine_id,scheduled_date,scheduled_time));
CREATE INDEX idx_times_medicine ON medicine_times(medicine_id);CREATE INDEX idx_logs_date ON dose_logs(scheduled_date);